query.sparql:
PREFIX gptkbp: <https://gptkb.org/prop/>
PREFIX gptkb: <https://gptkb.org/entity/>
SELECT ?dob WHERE { gptkb:Mahatma_Gandhi gptkbp:birthDate ?dob . }

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX gptkbp: <https://gptkb.org/prop/>
PREFIX gptkb: <https://gptkb.org/entity/>

SELECT ?mountain ?mountainLabel ?elev
WHERE {
  ?mountain gptkbp:instanceOf gptkb:mountain .
  ?mountain gptkbp:country gptkb:Italy .
  ?mountain gptkbp:elevation ?elev .

  OPTIONAL { ?mountain rdfs:label ?mountainLabel }

  {
    SELECT (MAX(xsd:decimal(REPLACE(str(?e), "[^0-9\\.\\-]", ""))) AS ?maxElev)
    WHERE {
      ?m gptkbp:instanceOf gptkb:mountain .
      ?m gptkbp:country gptkb:Italy .
      ?m gptkbp:elevation ?e .
    }
  }

  FILTER (
    xsd:decimal(REPLACE(str(?elev), "[^0-9\\.\\-]", "")) = ?maxElev
  )
}

PREFIX gptkbp: <https://gptkb.org/prop/>
PREFIX gptkb: <https://gptkb.org/entity/>

SELECT ?hostCity ?mainVenue
WHERE {
  gptkb:2012_Summer_Olympics
      gptkbp:hostCity ?hostCity ;
      gptkbp:mainVenue ?mainVenue .
}

PREFIX gptkbp: <https://gptkb.org/prop/>
PREFIX gptkb: <https://gptkb.org/entity/>

SELECT ?s WHERE {
  ?s gptkbp:influencedBy ?o .
  ?o gptkbp:influencedBy gptkb:Mahatma_Gandhi .
}

PREFIX gptkbp: <https://gptkb.org/prop/>
PREFIX gptkb: <https://gptkb.org/entity/>

SELECT ?s
WHERE {
  ?s gptkbp:headquarters gptkb:Mountain_View%2C_California .
}

PREFIX gptkbp: <https://gptkb.org/prop/>
PREFIX gptkb: <https://gptkb.org/entity/>

SELECT DISTINCT ?o
WHERE {
  {
    gptkb:Isaac_Newton gptkbp:influenced ?o .
  }
  UNION
  {
    ?o gptkbp:influenced gptkb:Isaac_Newton .
  }
}

PREFIX gptkb: <https://gptkb.org/entity/>
PREFIX gptkbp: <https://gptkb.org/prop/>

SELECT (COUNT(DISTINCT ?person) AS ?count)
WHERE {
  ?person gptkbp:nationality ?citizenship .
  VALUES ?citizenship {
    gptkb:German
    gptkb:French
  }
}

PREFIX gptkbp: <https://gptkb.org/prop/>
PREFIX gptkb: <https://gptkb.org/entity/>

SELECT DISTINCT ?work
WHERE {
  gptkb:A._A._Milne gptkbp:notableWork ?work .
}

PREFIX gptkbp: <https://gptkb.org/prop/>
PREFIX gptkb: <https://gptkb.org/entity/>

SELECT DISTINCT ?person ?field ?award ?organisation
WHERE {
  ?person gptkbp:instanceOf gptkb:person ;
          gptkbp:awardReceived ?award ;
          gptkbp:memberOf ?organisation .
  {
    ?person gptkbp:fieldOfWork ?field .
    FILTER(CONTAINS(LCASE(STR(?field)), "chemistry")
        || CONTAINS(LCASE(STR(?field)), "physics"))
  }
  UNION
  {
    ?person gptkbp:occupation ?occ .
    FILTER(?occ = gptkb:chemist
        || ?occ = gptkb:physicist)
    BIND(STR(?occ) AS ?field)
  }
}
ORDER BY ?person

PREFIX gptkb: <https://gptkb.org/entity/>
PREFIX gptkbp: <https://gptkb.org/prop/>

SELECT DISTINCT ?winner ?work WHERE {
  gptkb:Grammy_Award_for_Best_Male_Pop_Vocal_Performance_%281999%29
      gptkbp:winner ?winner ;
      gptkbp:winningWork ?work .
}

PREFIX gptkbp: <https://gptkb.org/prop/>
PREFIX gptkb: <https://gptkb.org/entity/>

SELECT DISTINCT ?person
WHERE {
  ?person gptkbp:instanceOf gptkb:person .
  FILTER NOT EXISTS {
    ?person gptkbp:birthPlace ?birthPlace .
  }
}

PREFIX gptkbp: <https://gptkb.org/prop/>
PREFIX gptkb: <https://gptkb.org/entity/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?person ?personName ?awardCount
WHERE {
  {
    SELECT ?person (COUNT(DISTINCT ?award) AS ?awardCount)
    WHERE {
      ?person gptkbp:instanceOf gptkb:person ;
              gptkbp:awardReceived ?award .
    }
    GROUP BY ?person
  }

  {
    SELECT (MAX(?ac) AS ?maxAwardCount)
    WHERE {
      SELECT ?person (COUNT(DISTINCT ?award) AS ?ac)
      WHERE {
        ?person gptkbp:instanceOf gptkb:person ;
                gptkbp:awardReceived ?award .
      }
      GROUP BY ?person
    }
  }

  OPTIONAL {
    ?person rdfs:label ?personName .
    FILTER(LANG(?personName) = "en")
  }

  FILTER(?awardCount = ?maxAwardCount)
}
ORDER BY ?person

PREFIX gptkb: <https://gptkb.org/entity/>
PREFIX gptkbp: <https://gptkb.org/prop/>

SELECT ?country (COUNT(DISTINCT ?person) AS ?count)
WHERE {
  ?person gptkbp:awardReceived gptkb:Emmy_Award ;
          gptkbp:awardReceived gptkb:Grammy_Award ;
          gptkbp:nationality ?country .
}
GROUP BY ?country

PREFIX gptkbp: <https://gptkb.org/prop/>
PREFIX gptkb: <https://gptkb.org/entity/>

SELECT DISTINCT ?person WHERE {
  ?person gptkbp:awardReceived gptkb:Academy_Award_for_Best_Director .
  ?person gptkbp:awardReceived gptkb:Golden_Globe_Award_for_Best_Director .
}

PREFIX gptkb: <https://gptkb.org/entity/>
PREFIX gptkbp: <https://gptkb.org/prop/>

ASK {
  gptkb:System_Manager gptkbp:abilities ?ability .
  FILTER(
    CONTAINS(LCASE(STR(?ability)), "problem solving")
  )
}

PREFIX gptkbp: <https://gptkb.org/prop/>
PREFIX gptkb: <https://gptkb.org/entity/>

SELECT DISTINCT ?person ?award
WHERE {
  ?person gptkbp:instanceOf gptkb:person ;
          gptkbp:memberOf gptkb:National_Academy_of_Sciences ;
          gptkbp:awardReceived ?award .
}

PREFIX gptkbp: <https://gptkb.org/prop/>
PREFIX gptkb: <https://gptkb.org/entity/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?person ?institution ?years
WHERE {
  {
    SELECT ?person ?institution ((xsd:integer(?termEnd) - xsd:integer(?termStart)) AS ?years)
    WHERE {
      ?person gptkbp:instanceOf gptkb:person ;
              gptkbp:president ?institution ;
              gptkbp:termStart ?termStart ;
              gptkbp:termEnd ?termEnd .
    }
  }

  {
    SELECT (MAX(?termLength) AS ?maxYears)
    WHERE {
      ?p gptkbp:instanceOf gptkb:person ;
         gptkbp:president ?inst ;
         gptkbp:termStart ?ts ;
         gptkbp:termEnd ?te .
      BIND((xsd:integer(?te) - xsd:integer(?ts)) AS ?termLength)
    }
  }

  FILTER(?years = ?maxYears)
}

PREFIX gptkbp: <https://gptkb.org/prop/>
PREFIX gptkb: <https://gptkb.org/entity/>

SELECT ?person
WHERE {
  ?person gptkbp:instanceOf gptkb:person ;
          gptkbp:birthPlace gptkb:France .
}
LIMIT 5

PREFIX gptkb: <https://gptkb.org/entity/>
PREFIX gptkbp: <https://gptkb.org/prop/>
SELECT ?person (COUNT(DISTINCT ?org) AS ?orgCount)
WHERE {
  ?person gptkbp:instanceOf gptkb:person ;
          gptkbp:memberOf ?org .
}
GROUP BY ?person
HAVING (COUNT(DISTINCT ?org) >= 2)
ORDER BY DESC(?orgCount)

PREFIX gptkb: <https://gptkb.org/entity/>
PREFIX gptkbp: <https://gptkb.org/prop/>

SELECT ?person ?workCount
WHERE {
  {
    SELECT ?person (COUNT(DISTINCT ?work) AS ?workCount)
    WHERE {
      ?person gptkbp:instanceOf gptkb:person ;
              gptkbp:notableWork ?work .
    }
    GROUP BY ?person
  }
  {
    SELECT (MAX(?c_inner) AS ?maxCount)
    WHERE {
      SELECT ?p_inner
             (COUNT(DISTINCT ?w_inner) AS ?c_inner)
      WHERE {
        ?p_inner gptkbp:instanceOf gptkb:person ;
                 gptkbp:notableWork ?w_inner .
      }
      GROUP BY ?p_inner
    }
  }
  FILTER(?workCount = ?maxCount)
}
